#!/bin/bash
sed -i '/import com.example.data.repository.PreferencesRepository/a import com.example.data.repository.MediaRepository\nimport com.example.data.repository.NoteRepository\nimport com.example.data.repository.ChecklistRepository\nimport com.example.data.repository.EventRepository\nimport com.example.data.repository.ExpenseRepository\nimport com.example.data.repository.VaultRepository' app/src/main/java/com/example/di/AppContainer.kt

sed -i '/val compassSensorManager: CompassSensorManager by lazy {/i \    val mediaRepository: MediaRepository by lazy {\n        MediaRepository(database.mediaDao())\n    }\n\n    val noteRepository: NoteRepository by lazy {\n        NoteRepository(database.noteDao())\n    }\n\n    val checklistRepository: ChecklistRepository by lazy {\n        ChecklistRepository(database.checklistDao())\n    }\n\n    val eventRepository: EventRepository by lazy {\n        EventRepository(database.eventDao())\n    }\n\n    val expenseRepository: ExpenseRepository by lazy {\n        ExpenseRepository(database.expenseDao())\n    }\n\n    val vaultRepository: VaultRepository by lazy {\n        VaultRepository(database.vaultDao(), secretManager)\n    }\n' app/src/main/java/com/example/di/AppContainer.kt
